/**
 * @method
 * @name searchFind
 * @description search Find 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchFind = async function () {
    $c.util.getComponent('dma_searchFindReq').set('pageNum', $c.util.getComponent("dma_searchFindReq").get("pageIndex"));
    $c.util.getComponent('dma_searchFindReq').set('method', 'searchCombinationReference');
    await scwin.tx_fn_searchFind('/main/search.do');
};

/**
 * @method
 * @name faqPopView
 * @description faq Pop View 처리
 * @param {String} _faqId _faqId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.faqPopView = async function (_faqId) {
